(()=>{const el=id=>document.getElementById(id),n=id=>Number(el(id).value)||0,fmt=(v,d=0)=>new Intl.NumberFormat('en-IE',{maximumFractionDigits:d}).format(v),eur=v=>'€'+fmt(v);function draw(){const units=n('calc-labs')*n('calc-hplc-count'),v=units*n('calc-flow')*60*n('calc-hours-day')*n('calc-days-week')*n('calc-weeks-year')/1000,upfront=units*(n('roi-unit-cost')+n('roi-install')),support=units*n('roi-support'),net=v*(n('calc-recovery')/100*n('calc-solvent-cost')+n('calc-waste-reduction')/100*n('calc-disposal-cost'))-support,r=n('roi-discount')/100;const cash=[0,1,2,3].map(y=>net*y-upfront),discount=[-upfront];for(let y=1;y<=3;y++)discount.push(discount[y-1]+net/Math.pow(1+r,y));const pay=net>0?upfront/net*12:null;el('return-payback').textContent=upfront===0?'No upfront cost':pay===null?'No payback':fmt(pay,1)+' months';el('return-roi').textContent=upfront?fmt(cash[3]/upfront*100,1)+'%':'N/A';el('return-npv').textContent=eur(discount[3]);el('return-basis').textContent=units+' units · '+eur(upfront)+' upfront · '+eur(support)+'/year total support · '+eur(net)+' annual net operating cash savings.';const W=880,H=400,L=115,R=30,T=30,B=80,low=Math.min(0,...cash,...discount),high=Math.max(0,...cash,...discount),raw=(high-low||1)/5,power=Math.pow(10,Math.floor(Math.log10(raw))),step=([1,2,5,10].find(k=>k*power>=raw)||10)*power,lo=Math.min(-step,Math.floor(low/step)*step),hi=Math.max(step,Math.ceil(high/step)*step),x=m=>L+m/36*(W-L-R),y=v=>T+(hi-v)/(hi-lo)*(H-T-B);let svg='<svg viewBox="0 0 '+W+' '+H+'" role="img" aria-label="Cumulative investment returns. Simple payback '+(pay===null?'not reached':fmt(pay,1)+' months')+'. Three-year net cash '+eur(cash[3])+', NPV '+eur(discount[3])+'." xmlns="http://www.w3.org/2000/svg">';for(let val=lo;val<=hi+step*.001;val+=step){svg+='<line x1="'+L+'" y1="'+y(val)+'" x2="'+(W-R)+'" y2="'+y(val)+'" stroke="'+(Math.abs(val)<step*.001?'#073e60':'#e0e8ee')+'" stroke-width="'+(Math.abs(val)<step*.001?2:1)+'"/><text x="'+(L-12)+'" y="'+(y(val)+4)+'" text-anchor="end" font-size="12" fill="#073e60">'+(val<0?'−':'')+'€'+fmt(Math.abs(val))+'</text>';}svg+='<line x1="'+L+'" y1="'+y(0)+'" x2="'+(W-R)+'" y2="'+y(0)+'" stroke="#073e60" stroke-width="2"/><text x="'+(W-R)+'" y="'+(y(0)-8)+'" text-anchor="end" font-size="12" fill="#526b7b">Break-even €0</text>';for(const m of [0,6,12,18,24,30,36])svg+='<text x="'+x(m)+'" y="'+(H-B+24)+'" text-anchor="middle" font-size="12" fill="#526b7b">'+m+' mo</text>';svg+='<text x="'+((L+W-R)/2)+'" y="'+(H-15)+'" text-anchor="middle" font-size="14" font-weight="700" fill="#073e60">Time since installation (months)</text><text transform="translate(20 '+((T+H-B)/2)+') rotate(-90)" text-anchor="middle" font-size="14" font-weight="700" fill="#073e60">Cumulative net value (€)</text>';for(const[vals,color,dash]of [[cash,'#16804a',''],[discount,'#59a879','6 4']]){svg+='<polyline fill="none" stroke="'+color+'" stroke-width="3" stroke-dasharray="'+dash+'" points="'+vals.map((v,i)=>x(i*12)+','+y(v)).join(' ')+'"/>';vals.forEach((v,i)=>{svg+='<circle cx="'+x(i*12)+'" cy="'+y(v)+'" r="4" fill="'+color+'"><title>Year '+i+': '+eur(v)+'</title></circle>';});}if(pay!==null&&pay<=36&&upfront>0){svg+='<line x1="'+x(pay)+'" y1="'+y(0)+'" x2="'+x(pay)+'" y2="'+(H-B)+'" stroke="#16804a" stroke-dasharray="3 3"/><circle cx="'+x(pay)+'" cy="'+y(0)+'" r="6" fill="#fff" stroke="#16804a" stroke-width="3"/><text x="'+(x(pay)+10)+'" y="'+(y(0)+22)+'" font-size="13" font-weight="700" fill="#073e60">Payback '+fmt(pay,1)+' months · €0</text>';}el('return-chart').innerHTML=svg+'<g id="return-selected"></g></svg>';
let controls=el('return-explore');if(!controls){controls=document.createElement('div');controls.id='return-explore';el('return-chart').after(controls);}
controls.innerHTML='<p class="small">Hover or tap the chart to inspect each year, or select a point below.</p><div class="return-point-buttons">'+[0,1,2,3].map(i=>'<button type="button" data-year="'+i+'">'+(i?'Year '+i:'At installation')+'</button>').join('')+(pay!==null&&pay<=36&&upfront>0?'<button type="button" data-payback>Payback point</button>':'')+'</div><div id="return-point-detail" aria-live="polite"></div>';
function select(i){const m=i*12;el('return-selected').innerHTML='<line x1="'+x(m)+'" x2="'+x(m)+'" y1="'+T+'" y2="'+(H-B)+'" stroke="#526b7b" stroke-dasharray="3 4"/><circle cx="'+x(m)+'" cy="'+y(cash[i])+'" r="7" fill="#fff" stroke="#16804a" stroke-width="3"/><circle cx="'+x(m)+'" cy="'+y(discount[i])+'" r="7" fill="#fff" stroke="#59a879" stroke-width="3"/>';el('return-point-detail').textContent=(i?'End of year '+i:'At installation')+' · Net cash benefit: '+eur(cash[i])+' · NPV: '+eur(discount[i]);controls.querySelectorAll('button').forEach(btn=>btn.setAttribute('aria-pressed',String(btn.dataset.year===String(i))));}
controls.querySelectorAll('[data-year]').forEach(btn=>btn.onclick=()=>select(Number(btn.dataset.year)));
const pb=controls.querySelector('[data-payback]');if(pb)pb.onclick=()=>{el('return-selected').innerHTML='<circle cx="'+x(pay)+'" cy="'+y(0)+'" r="10" fill="none" stroke="#f58220" stroke-width="3"/>';el('return-point-detail').textContent='Simple payback: '+fmt(pay,1)+' months · Cumulative net cash benefit: €0. Upfront investment recovered after support costs. NPV is valued separately at year-end.';controls.querySelectorAll('button').forEach(btn=>btn.setAttribute('aria-pressed',String(btn===pb)));};
const chart=el('return-chart').querySelector('svg');function inspect(e){const point=chart.createSVGPoint();point.x=e.clientX;point.y=e.clientY;const px=point.matrixTransform(chart.getScreenCTM().inverse()).x;select(Math.max(0,Math.min(3,Math.round((px-L)/(W-L-R)*3))));}chart.addEventListener('pointermove',e=>{if(e.pointerType==='mouse')inspect(e)});chart.addEventListener('click',inspect);select(3);}document.addEventListener('resolve-model',draw);el('calc-reset').addEventListener('click',draw);draw();})();